window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f6c1d13dd00cecbb"]={"versions": [{"id": "FIG-f6c1d13dd00cecbb", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / AUTOSAR ECUC-Metamodell (ECU Configuration Parameter Definition).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release R23-11), BSW-Modul <code>Firewall</code> (<code>Fw</code>).</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li>Spezifikation des Konfigurationscontainers <code>FirewallNetworkLayerIcmpConfig</code> zur Regelerstellung auf Vermittlungsschicht-Ebene (OSI Layer 3 / Network Layer).</li>\n<li>Dient dem Konfigurationsgenerator zur Erzeugung statischer Regeltabellen für die Filterung und Integritätsprüfung von ICMPv4- (RFC 792) und ICMPv6-Verkehr (RFC 4443).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Container-Definition:</strong></li>\n<li><code>FirewallNetworkLayerIcmpConfig</code> (<code>EcucParamConfContainerDef</code>):</li>\n<li>Multiplizität: <code>0..1</code> (optionaler Kind-Container innerhalb einer IP-Regelkonfiguration).</li>\n<li><strong>Parameter-Definitionen (Komposition via <code>+parameter</code>):</strong></li>\n<li><code>FirewallChecksumVerification</code> (<code>EcucBooleanParamDef</code>):</li>\n<li>Multiplizität: <code>0..1</code> (optional).</li>\n<li>Typ: <code>Boolean</code>.</li>\n<li>Semantik: Aktiviert/deaktiviert die Verifikation der ICMP-Prüfsumme vor der Regelauswertung.</li>\n<li><code>FirewallIcmpType</code> (<code>EcucIntegerParamDef</code>):</li>\n<li>Multiplizität: <code>1</code> (Default).</li>\n<li>Wertebereich: <code>min = 0</code>, <code>max = 65535</code> (<code>uint16</code>).</li>\n<li>Semantik: Spezifiziert den zu filternden ICMP-Nachrichtentyp (z. B. Echo Request, Destination Unreachable).</li>\n<li><code>FirewallIcmpCode</code> (<code>EcucIntegerParamDef</code>):</li>\n<li>Multiplizität: <code>1</code> (Default).</li>\n<li>Wertebereich: <code>min = 0</code>, <code>max = 65535</code> (<code>uint16</code>).</li>\n<li>Semantik: Spezifiziert den nachgelagerten ICMP-Code zur feingranularen Filterung innerhalb eines Typs.</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li>Strenge Komposition (<code>+parameter</code>): Der Container kapselt exklusiv bis zu drei Parameterinstanzen zur Parametrisierung eines ICMP-Filters.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Konfigurationsmetamodell handelt, ergibt sich das dynamische Verhalten aus der Laufzeit-Evaluierung im BSW-Stack:</em></p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Empfang eines IP-Datagramms mit <code>Protocol</code> (IPv4) = <code>1</code> bzw. <code>Next Header</code> (IPv6) = <code>58</code> via Ethernet-Interface / <code>SoAd</code> / <code>TcpIp</code>.</li>\n<li><strong>Checksum-Prüfung:</strong> Falls <code>FirewallChecksumVerification == TRUE</code>, erfolgt die synchrone Neuberechnung und Validierung der ICMP-Prüfsumme über den Frame-Payload (ggf. inkl. IPv6-Pseudoheader). Bei Diskrepanz: Direkter Paket-Drop; Det-/IdsM-Sicherheitsmeldung.</li>\n<li><strong>Feld-Matching:</strong> Extrahieren der 8-Bit-Felder für ICMP-Type und ICMP-Code aus dem Header.</li>\n<li><strong>Regel-Evaluierung:</strong> Abgleich der extrahierten Werte gegen <code>FirewallIcmpType</code> und <code>FirewallIcmpCode</code>.</li>\n<li><strong>Aktion:</strong> Treffer führt zur konfigurierten Regelaktion (Pass/Drop/Forwarding-Entscheidung).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SWS-Anforderungen:</strong> Implementiert <code>ECUC_Fw_00025</code> (Container-Spezifikation) und <code>ECUC_Fw_00130</code> (Parameter-Definitionen).</li>\n<li><strong>BSW-Code-Generierung:</strong></li>\n<li>Der Generator bildet den Container auf statische, <code>const</code>-qualifizierte ROM-Strukturen ab (z. B. <code>Fw_IcmpConfigType</code>). Keine dynamische Speicherallokation im Fast-Path.</li>\n<li><strong>Wertebereichs-Anomalie (Entwickler-Falle):</strong></li>\n<li>Obwohl ICMP Type und Code nach RFC strikt 8-Bit-Felder sind (<code>0..255</code>), modelliert AUTOSAR den Wertebereich bis <code>65535</code> (<code>uint16</code>).</li>\n<li>Treiber- und Stack-Implementierer müssen im Generator Validierungsprüfungen vorsehen, um ungültige Werte <code>&gt; 255</code> abzufangen oder festzustellen, ob Stack-Hersteller Werte außerhalb des 8-Bit-Bereichs als Wildcards (z. B. <code>0xFFFF</code> für \"Any Code\") interpretieren.</li>\n<li><strong>Performance & HW-Offloading:</strong></li>\n<li>Das Setzen von <code>FirewallChecksumVerification = TRUE</code> ohne Ethernet-Controller-Checksum-Offloading bindet erhebliche CPU-Zyklen im Interrupt-/Task-Kontext der Firewall, da die Checksumme softwareseitig über den gesamten ICMP-Payload berechnet werden muss.</li>\n</ul>"}, {"id": "FIG-c1eabb3307d6519b", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / AUTOSAR ECUC-Metamodell (ECU Configuration Parameter Definition).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release R23-11), BSW-Modul <code>Firewall</code> (<code>Fw</code>).</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li>Spezifikation des Konfigurationscontainers <code>FirewallNetworkLayerIcmpConfig</code> zur Regelerstellung auf Vermittlungsschicht-Ebene (OSI Layer 3 / Network Layer).</li>\n<li>Dient dem Konfigurationsgenerator zur Erzeugung statischer Regeltabellen für die Filterung und Integritätsprüfung von ICMPv4- (RFC 792) und ICMPv6-Verkehr (RFC 4443).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Container-Definition:</strong></li>\n<li><code>FirewallNetworkLayerIcmpConfig</code> (<code>EcucParamConfContainerDef</code>):</li>\n<li>Multiplizität: <code>0..1</code> (optionaler Kind-Container innerhalb einer IP-Regelkonfiguration).</li>\n<li><strong>Parameter-Definitionen (Komposition via <code>+parameter</code>):</strong></li>\n<li><code>FirewallChecksumVerification</code> (<code>EcucBooleanParamDef</code>):</li>\n<li>Multiplizität: <code>0..1</code> (optional).</li>\n<li>Typ: <code>Boolean</code>.</li>\n<li>Semantik: Aktiviert/deaktiviert die Verifikation der ICMP-Prüfsumme vor der Regelauswertung.</li>\n<li><code>FirewallIcmpType</code> (<code>EcucIntegerParamDef</code>):</li>\n<li>Multiplizität: <code>1</code> (Default).</li>\n<li>Wertebereich: <code>min = 0</code>, <code>max = 65535</code> (<code>uint16</code>).</li>\n<li>Semantik: Spezifiziert den zu filternden ICMP-Nachrichtentyp (z. B. Echo Request, Destination Unreachable).</li>\n<li><code>FirewallIcmpCode</code> (<code>EcucIntegerParamDef</code>):</li>\n<li>Multiplizität: <code>1</code> (Default).</li>\n<li>Wertebereich: <code>min = 0</code>, <code>max = 65535</code> (<code>uint16</code>).</li>\n<li>Semantik: Spezifiziert den nachgelagerten ICMP-Code zur feingranularen Filterung innerhalb eines Typs.</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li>Strenge Komposition (<code>+parameter</code>): Der Container kapselt exklusiv bis zu drei Parameterinstanzen zur Parametrisierung eines ICMP-Filters.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Konfigurationsmetamodell handelt, ergibt sich das dynamische Verhalten aus der Laufzeit-Evaluierung im BSW-Stack:</em></p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Empfang eines IP-Datagramms mit <code>Protocol</code> (IPv4) = <code>1</code> bzw. <code>Next Header</code> (IPv6) = <code>58</code> via Ethernet-Interface / <code>SoAd</code> / <code>TcpIp</code>.</li>\n<li><strong>Checksum-Prüfung:</strong> Falls <code>FirewallChecksumVerification == TRUE</code>, erfolgt die synchrone Neuberechnung und Validierung der ICMP-Prüfsumme über den Frame-Payload (ggf. inkl. IPv6-Pseudoheader). Bei Diskrepanz: Direkter Paket-Drop; Det-/IdsM-Sicherheitsmeldung.</li>\n<li><strong>Feld-Matching:</strong> Extrahieren der 8-Bit-Felder für ICMP-Type und ICMP-Code aus dem Header.</li>\n<li><strong>Regel-Evaluierung:</strong> Abgleich der extrahierten Werte gegen <code>FirewallIcmpType</code> und <code>FirewallIcmpCode</code>.</li>\n<li><strong>Aktion:</strong> Treffer führt zur konfigurierten Regelaktion (Pass/Drop/Forwarding-Entscheidung).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SWS-Anforderungen:</strong> Implementiert <code>ECUC_Fw_00025</code> (Container-Spezifikation) und <code>ECUC_Fw_00130</code> (Parameter-Definitionen).</li>\n<li><strong>BSW-Code-Generierung:</strong></li>\n<li>Der Generator bildet den Container auf statische, <code>const</code>-qualifizierte ROM-Strukturen ab (z. B. <code>Fw_IcmpConfigType</code>). Keine dynamische Speicherallokation im Fast-Path.</li>\n<li><strong>Wertebereichs-Anomalie (Entwickler-Falle):</strong></li>\n<li>Obwohl ICMP Type und Code nach RFC strikt 8-Bit-Felder sind (<code>0..255</code>), modelliert AUTOSAR den Wertebereich bis <code>65535</code> (<code>uint16</code>).</li>\n<li>Treiber- und Stack-Implementierer müssen im Generator Validierungsprüfungen vorsehen, um ungültige Werte <code>&gt; 255</code> abzufangen oder festzustellen, ob Stack-Hersteller Werte außerhalb des 8-Bit-Bereichs als Wildcards (z. B. <code>0xFFFF</code> für \"Any Code\") interpretieren.</li>\n<li><strong>Performance & HW-Offloading:</strong></li>\n<li>Das Setzen von <code>FirewallChecksumVerification = TRUE</code> ohne Ethernet-Controller-Checksum-Offloading bindet erhebliche CPU-Zyklen im Interrupt-/Task-Kontext der Firewall, da die Checksumme softwareseitig über den gesamten ICMP-Payload berechnet werden muss.</li>\n</ul>"}, {"id": "FIG-1e8ff4c4ab4e357e", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / AUTOSAR ECUC-Metamodell (ECU Configuration Parameter Definition).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release R23-11), BSW-Modul <code>Firewall</code> (<code>Fw</code>).</li>\n<li><strong>Funktionale Einordnung:</strong></li>\n<li>Spezifikation des Konfigurationscontainers <code>FirewallNetworkLayerIcmpConfig</code> zur Regelerstellung auf Vermittlungsschicht-Ebene (OSI Layer 3 / Network Layer).</li>\n<li>Dient dem Konfigurationsgenerator zur Erzeugung statischer Regeltabellen für die Filterung und Integritätsprüfung von ICMPv4- (RFC 792) und ICMPv6-Verkehr (RFC 4443).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Container-Definition:</strong></li>\n<li><code>FirewallNetworkLayerIcmpConfig</code> (<code>EcucParamConfContainerDef</code>):</li>\n<li>Multiplizität: <code>0..1</code> (optionaler Kind-Container innerhalb einer IP-Regelkonfiguration).</li>\n<li><strong>Parameter-Definitionen (Komposition via <code>+parameter</code>):</strong></li>\n<li><code>FirewallChecksumVerification</code> (<code>EcucBooleanParamDef</code>):</li>\n<li>Multiplizität: <code>0..1</code> (optional).</li>\n<li>Typ: <code>Boolean</code>.</li>\n<li>Semantik: Aktiviert/deaktiviert die Verifikation der ICMP-Prüfsumme vor der Regelauswertung.</li>\n<li><code>FirewallIcmpType</code> (<code>EcucIntegerParamDef</code>):</li>\n<li>Multiplizität: <code>1</code> (Default).</li>\n<li>Wertebereich: <code>min = 0</code>, <code>max = 65535</code> (<code>uint16</code>).</li>\n<li>Semantik: Spezifiziert den zu filternden ICMP-Nachrichtentyp (z. B. Echo Request, Destination Unreachable).</li>\n<li><code>FirewallIcmpCode</code> (<code>EcucIntegerParamDef</code>):</li>\n<li>Multiplizität: <code>1</code> (Default).</li>\n<li>Wertebereich: <code>min = 0</code>, <code>max = 65535</code> (<code>uint16</code>).</li>\n<li>Semantik: Spezifiziert den nachgelagerten ICMP-Code zur feingranularen Filterung innerhalb eines Typs.</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li>Strenge Komposition (<code>+parameter</code>): Der Container kapselt exklusiv bis zu drei Parameterinstanzen zur Parametrisierung eines ICMP-Filters.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Konfigurationsmetamodell handelt, ergibt sich das dynamische Verhalten aus der Laufzeit-Evaluierung im BSW-Stack:</em></p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Empfang eines IP-Datagramms mit <code>Protocol</code> (IPv4) = <code>1</code> bzw. <code>Next Header</code> (IPv6) = <code>58</code> via Ethernet-Interface / <code>SoAd</code> / <code>TcpIp</code>.</li>\n<li><strong>Checksum-Prüfung:</strong> Falls <code>FirewallChecksumVerification == TRUE</code>, erfolgt die synchrone Neuberechnung und Validierung der ICMP-Prüfsumme über den Frame-Payload (ggf. inkl. IPv6-Pseudoheader). Bei Diskrepanz: Direkter Paket-Drop; Det-/IdsM-Sicherheitsmeldung.</li>\n<li><strong>Feld-Matching:</strong> Extrahieren der 8-Bit-Felder für ICMP-Type und ICMP-Code aus dem Header.</li>\n<li><strong>Regel-Evaluierung:</strong> Abgleich der extrahierten Werte gegen <code>FirewallIcmpType</code> und <code>FirewallIcmpCode</code>.</li>\n<li><strong>Aktion:</strong> Treffer führt zur konfigurierten Regelaktion (Pass/Drop/Forwarding-Entscheidung).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SWS-Anforderungen:</strong> Implementiert <code>ECUC_Fw_00025</code> (Container-Spezifikation) und <code>ECUC_Fw_00130</code> (Parameter-Definitionen).</li>\n<li><strong>BSW-Code-Generierung:</strong></li>\n<li>Der Generator bildet den Container auf statische, <code>const</code>-qualifizierte ROM-Strukturen ab (z. B. <code>Fw_IcmpConfigType</code>). Keine dynamische Speicherallokation im Fast-Path.</li>\n<li><strong>Wertebereichs-Anomalie (Entwickler-Falle):</strong></li>\n<li>Obwohl ICMP Type und Code nach RFC strikt 8-Bit-Felder sind (<code>0..255</code>), modelliert AUTOSAR den Wertebereich bis <code>65535</code> (<code>uint16</code>).</li>\n<li>Treiber- und Stack-Implementierer müssen im Generator Validierungsprüfungen vorsehen, um ungültige Werte <code>&gt; 255</code> abzufangen oder festzustellen, ob Stack-Hersteller Werte außerhalb des 8-Bit-Bereichs als Wildcards (z. B. <code>0xFFFF</code> für \"Any Code\") interpretieren.</li>\n<li><strong>Performance & HW-Offloading:</strong></li>\n<li>Das Setzen von <code>FirewallChecksumVerification = TRUE</code> ohne Ethernet-Controller-Checksum-Offloading bindet erhebliche CPU-Zyklen im Interrupt-/Task-Kontext der Firewall, da die Checksumme softwareseitig über den gesamten ICMP-Payload berechnet werden muss.</li>\n</ul>"}], "trans": [{"from": "FIG-f6c1d13dd00cecbb", "to": "FIG-c1eabb3307d6519b", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c1eabb3307d6519b", "to": "FIG-1e8ff4c4ab4e357e", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
